// CSD_RATIONALE_BEGIN
// This CSD strategy generates free-form reasoning text until it encounters "<<",
// then enters a constrained phase where it focuses on producing arithmetic expressions
// containing variables. To prevent premature closure of expressions, we use logit
// manipulation to penalize the ">" token when the expression is too short. We also
// use the ConfidenceGatedStep helper to ensure that the model does not prematurely
// close expressions by choosing the highest logit token when it agrees with the grammar.
// CSD_RATIONALE_END

generated := [];
var steps := 0;
var insideConstrained := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token ::
    t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  invariant helpers.cost == steps
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE (using ConfidenceGatedStep):
    var next, _ := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true; currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    // CONSTRAINED PHASE:
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // RAW pattern with logit manipulation:
      lm.GenerateLogits(prompt + generated);
      if |currentConstrained| < 5 { helpers.PenalizeTokenLogits(lm, [">>"], 3.0); }
      helpers.BoostTokenLogits(lm, parser.ValidNextTokens(currentConstrained), 5.0);
      var next := lm.ChooseNextToken();
      helpers.cost := helpers.cost + 1;
      generated := generated + [next]; steps := steps + 1;
      if parser.IsValidPrefix(currentConstrained + [next]) {
        currentConstrained := currentConstrained + [next];
        if Contains(next, ">>") { insideConstrained := false; }
      } else { insideConstrained := false; }
    }
  }
}
cost := helpers.cost;

